using System.IO;
using System.Text.Json;

namespace geoDC.UiDriver;

/// <summary>
///     A project package the UI driver may open, generated by the test-data generator CLI into
///     <c>dev/sample-projects/</c> in the <see cref="DriverHome" />. Each sample project has three files: the package, the Shore Control Register beside
///     it (<see cref="DriverRegister" />), and a provenance file that records the seed and fingerprints that produced
///     them.
/// </summary>
/// <param name="Name">The package's file name without extension, such as <c>sample</c>.</param>
/// <param name="Preset">The generator preset that builds it.</param>
/// <param name="Scenario">How the provenance file describes the scenario.</param>
public sealed record DriverSampleProject(string Name, string Preset, string Scenario)
{
    /// <summary>The folder the sample projects live in, relative to the driver home.</summary>
    public const string SampleProjectDirectory = "dev/sample-projects";

    /// <summary>
    ///     The default sample project: one job, an open pitch calibration cycle, a misaligned set-up survey and shore
    ///     control.
    /// </summary>
    public static readonly DriverSampleProject Default = new("sample", "sample", "minimal");

    /// <summary>
    ///     Work items in every workflow state, readiness and outcome. It is a separate package because the default
    ///     sample project's misaligned set-up would bias every outcome.
    /// </summary>
    public static readonly DriverSampleProject Lifecycle = new("sample-lifecycle", "lifecycle-coverage",
        "default+lifecycle-coverage");

    private static readonly JsonSerializerOptions ProvenanceJsonOptions = new()
    {
        WriteIndented = true,
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase
    };

    /// <summary>Every sample project, in the order <c>sample status</c> lists them.</summary>
    public static IReadOnlyList<DriverSampleProject> All { get; } = [Default, Lifecycle];

    /// <summary>The package, relative to the driver home.</summary>
    public string PackagePath => $"{SampleProjectDirectory}/{Name}.gdcproj";

    /// <summary>The Shore Control Register beside the package, relative to the driver home.</summary>
    public string RegisterPath => $"{SampleProjectDirectory}/{Name}-register.sqlite";

    /// <summary>The provenance file, relative to the driver home.</summary>
    public string ProvenancePath => $"{SampleProjectDirectory}/{Name}.fingerprint.json";

    /// <summary>
    ///     The test-data generator CLI's arguments after <c>--</c>, writing into <paramref name="stagingDirectory" />.
    /// </summary>
    public IReadOnlyList<string> GeneratorArguments(string stagingDirectory)
    {
        return [stagingDirectory, $"--preset={Preset}"];
    }

    /// <summary>
    ///     Reads the seed, the preset and the fingerprints from the generator's console output. The register lines are
    ///     present only when the preset writes a register.
    /// </summary>
    /// <exception cref="DriverException">
    ///     <c>sample-project-generator-output</c> when a line every run prints is missing.
    /// </exception>
    public SampleProjectProvenance ReadProvenance(IReadOnlyList<string> generatorOutput, DateTime generatedUtc)
    {
        string? registerFingerprint = LastValue(generatorOutput, "Register fingerprint");
        return new SampleProjectProvenance(
            int.Parse(RequireValue(generatorOutput, "Seed"), System.Globalization.CultureInfo.InvariantCulture),
            RequireValue(generatorOutput, "Preset"),
            Scenario,
            RequireValue(generatorOutput, "Domain fingerprint"),
            RequireValue(generatorOutput, "Project fingerprint"),
            registerFingerprint,
            generatedUtc);
    }

    /// <summary>
    ///     The register file the generator wrote, from its <c>Register:</c> line, or null when it wrote none.
    /// </summary>
    public static string? GeneratedRegisterPath(IReadOnlyList<string> generatorOutput)
    {
        return LastValue(generatorOutput, "Register");
    }

    /// <summary>
    ///     Copies the generated package and register from <paramref name="stagingDirectory" /> into the sample project
    ///     folder under <paramref name="driverHome" />, and writes the provenance file. A preset without a register
    ///     removes the last one, so the UI driver never gives geoDC a register from another seed.
    /// </summary>
    public void Install(string driverHome, string stagingDirectory, string? generatedRegister,
        SampleProjectProvenance provenance)
    {
        Directory.CreateDirectory(Path.Combine(driverHome, SampleProjectDirectory));
        File.Copy(Path.Combine(stagingDirectory, "TestProject.gdcproj"), Path.Combine(driverHome, PackagePath), true);
        string register = Path.Combine(driverHome, RegisterPath);
        if (generatedRegister is not null && File.Exists(generatedRegister))
        {
            File.Copy(generatedRegister, register, true);
        }
        else
        {
            File.Delete(register);
        }

        File.WriteAllText(Path.Combine(driverHome, ProvenancePath),
            JsonSerializer.Serialize(provenance, ProvenanceJsonOptions));
    }

    /// <summary>What is on disk for this sample project under <paramref name="driverHome" />.</summary>
    public SampleProjectState ReadState(string driverHome)
    {
        string provenanceFile = Path.Combine(driverHome, ProvenancePath);
        SampleProjectProvenance? provenance = null;
        if (File.Exists(provenanceFile))
        {
            try
            {
                provenance = JsonSerializer.Deserialize<SampleProjectProvenance>(File.ReadAllText(provenanceFile),
                    ProvenanceJsonOptions);
            }
            catch (JsonException)
            {
                // A provenance file that cannot be read counts as missing, so the sample project needs creating again.
            }
        }

        return new SampleProjectState(this, File.Exists(Path.Combine(driverHome, PackagePath)),
            File.Exists(Path.Combine(driverHome, RegisterPath)), provenance);
    }

    private static string RequireValue(IReadOnlyList<string> lines, string label)
    {
        return LastValue(lines, label) ?? throw new DriverException("sample-project-generator-output",
            $"The test-data generator's output has no '{label}:' line, so the sample project's provenance is unknown.",
            1);
    }

    // The value of the last "<label>: value" line. The label must be followed directly by the colon, so "Register"
    // does not match "Register fingerprint: ...".
    private static string? LastValue(IReadOnlyList<string> lines, string label)
    {
        string prefix = label + ":";
        string? value = null;
        foreach (string line in lines)
        {
            if (line.StartsWith(prefix, StringComparison.Ordinal))
            {
                value = line[prefix.Length..].Trim();
            }
        }

        return value;
    }
}

/// <summary>Which generator run produced a sample project, as its provenance file records it.</summary>
/// <param name="Seed">The random seed the preset used.</param>
/// <param name="Preset">The generator preset.</param>
/// <param name="Scenario">How the scenario is described, such as <c>minimal</c>.</param>
/// <param name="DomainFingerprint">The generator's ID-agnostic fingerprint of the scenario.</param>
/// <param name="ProjectFingerprint">The fingerprint of the package as persisted.</param>
/// <param name="RegisterFingerprint">The register's fingerprint, or null when the preset writes no register.</param>
/// <param name="GeneratedUtc">When the sample project was created.</param>
public sealed record SampleProjectProvenance(
    int Seed,
    string Preset,
    string Scenario,
    string DomainFingerprint,
    string ProjectFingerprint,
    string? RegisterFingerprint,
    DateTime GeneratedUtc);

/// <summary>A sample project as <c>sample status</c> reports it.</summary>
/// <param name="SampleProject">The sample project.</param>
/// <param name="PackageExists">True when the package is on disk.</param>
/// <param name="RegisterExists">True when its register is on disk.</param>
/// <param name="Provenance">What its provenance file records, or null when there is no readable one.</param>
public sealed record SampleProjectState(
    DriverSampleProject SampleProject,
    bool PackageExists,
    bool RegisterExists,
    SampleProjectProvenance? Provenance)
{
    /// <summary>
    ///     True when the package and its provenance file are both there, so launches and captures can use it.
    /// </summary>
    public bool Ready => PackageExists && Provenance is not null;
}